section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/retro-format-rotation-guide.json",
  "title": "RotationGuide",
  "type": "object",
  "required": ["team_id", "owner", "guide_date", "history", "format_last_used", "team_state", "stale_formats", "refresh_trend", "outcome_review"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "format": {"enum": ["start-stop-continue", "sailboat", "4ls", "timeline", "anonymous-async", "mad-sad-glad", "lean-coffee"]},
    "count": {"type": "integer", "minimum": 0}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "team_id": {"type": "string", "minLength": 2},
    "owner": {"type": "string", "minLength": 2, "pattern": "^[^#@]+$", "not": {"pattern": "(?i)^(team|everyone|the team|all|tbd|channel)$"}},
    "guide_date": {"$ref": "#/definitions/date"},
    "history": {
      "type": "array",
      "maxItems": 3,
      "items": {
        "type": "object",
        "required": ["retro_date", "instance_ref", "format", "action_items", "participants", "silent_participants"],
        "properties": {
          "retro_date": {"$ref": "#/definitions/date"},
          "instance_ref": {"type": "string", "minLength": 5},
          "format": {"$ref": "#/definitions/format"},
          "action_items": {"$ref": "#/definitions/count"},
          "participants": {"$ref": "#/definitions/count"},
          "silent_participants": {"$ref": "#/definitions/count"}
        }
      }
    },
    "format_last_used": {
      "type": "object",
      "required": ["start-stop-continue", "sailboat", "4ls", "timeline", "anonymous-async", "mad-sad-glad", "lean-coffee"],
      "additionalProperties": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]}
    },
    "team_state": {
      "type": "object",
      "required": ["distribution", "fatigue_signal"],
      "properties": {
        "distribution": {"enum": ["async", "hybrid", "in-person"]},
        "fatigue_signal": {"enum": ["fresh", "rotating", "fatigued"]}
      }
    },
    "stale_formats": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["format", "signal"],
        "properties": {
          "format": {"$ref": "#/definitions/format"},
          "signal": {"enum": ["twice_in_last_3", "action_items_dropped_over_50pct", "two_or_more_silent_participants"]}
        }
      }
    },
    "refresh_trend": {
      "type": "object",
      "required": ["consecutive_rotations_without_refresh", "escalation"],
      "properties": {
        "consecutive_rotations_without_refresh": {"type": "integer", "minimum": 0, "maximum": 2},
        "escalation": {"enum": ["none", "fatigue_is_not_a_format_problem"]},
        "team_health_route": {"enum": ["team-morale-pulse-survey", "solo-burnout-tripwires"]}
      },
      "if": {"properties": {"consecutive_rotations_without_refresh": {"const": 2}}},
      "then": {"properties": {"escalation": {"const": "fatigue_is_not_a_format_problem"}}, "required": ["team_health_route"]}
    },
    "skip": {"const": "history < 3"},
    "pick": {
      "type": "object",
      "required": ["next_format", "tie_breaker", "exception_recorded", "next_format_last_used", "anonymous_async_input"],
      "properties": {
        "next_format": {"$ref": "#/definitions/format"},
        "tie_breaker": {"enum": ["no_repeat_only", "async_pool", "async_pool_exhausted", "fatigued_12_month_lookback", "in_person_sailboat_or_lean_coffee", "reflective_mid_cycle_4ls"]},
        "exception_recorded": {"type": "boolean"},
        "next_format_last_used": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]},
        "anonymous_async_input": {"type": "boolean"}
      },
      "if": {"properties": {"exception_recorded": {"const": true}}},
      "then": {"properties": {"tie_breaker": {"const": "async_pool_exhausted"}}}
    },
    "rationale": {"type": "string", "minLength": 20, "not": {"pattern": "(?i)(everyone likes it|seemed right|we always)"}},
    "outcome_review": {
      "type": "object",
      "required": ["cadence", "last_run_at"],
      "properties": {
        "cadence": {"enum": ["next-retro", "monthly", "quarterly"]},
        "last_run_at": {"$ref": "#/definitions/date"}
      }
    }
  },
  "allOf": [
    {"if": {"properties": {"history": {"maxItems": 2}}}, "then": {"required": ["skip"], "not": {"required": ["pick"]}}},
    {"if": {"properties": {"history": {"minItems": 3}, "refresh_trend": {"properties": {"escalation": {"const": "none"}}}}, "required": ["refresh_trend"]}, "then": {"required": ["pick", "rationale"]}},
    {"if": {"properties": {"refresh_trend": {"properties": {"escalation": {"const": "fatigue_is_not_a_format_problem"}}}}, "required": ["refresh_trend"]}, "then": {"not": {"required": ["pick"]}}},
    {"if": {"properties": {"team_state": {"properties": {"distribution": {"const": "async"}}}}, "required": ["pick"]}, "then": {"properties": {"pick": {"properties": {"next_format": {"not": {"enum": ["mad-sad-glad", "lean-coffee"]}}, "anonymous_async_input": {"const": true}}}}}},
    {"if": {"properties": {"team_state": {"properties": {"fatigue_signal": {"const": "fatigued"}}}}, "required": ["pick"]}, "then": {"properties": {"pick": {"properties": {"tie_breaker": {"const": "fatigued_12_month_lookback"}}}}}}
  ]
}
